SELECT c.company_id, c.company_code, a.user_account_id, e.employee_no, a.email
FROM user_account a
JOIN company c  ON c.company_id = a.company_id
JOIN employee e ON e.company_id = a.company_id AND e.employee_id = a.employee_id
WHERE a.company_id = #{companyId}
  AND a.user_account_id = #{userAccountId}

SELECT sent_count
FROM email_rate_limit
WHERE company_id = #{companyId} AND email = #{email}
  AND purpose_code =  AND quota_date = #{today}

