UPDATE email_verification
SET revoked_at = #{now}, updated_at = #{now}
WHERE company_id = #{companyId} AND user_account_id = #{userAccountId}
  AND purpose_code = 
  AND consumed_at IS NULL AND revoked_at IS NULL

UPDATE email_verification
SET failed_count = failed_count + 1,
    revoked_at = CASE WHEN failed_count + 1 >= #{maxFailures} THEN #{now} END,
    updated_at = #{now}
WHERE email_verification_id = #{id} AND company_id = #{companyId}
  AND verified_at IS NULL AND revoked_at IS NULL

UPDATE email_verification
SET token_hash = #{tokenHash}, verified_at = #{now}, expires_at = #{expiresAt}, updated_at = #{now}
WHERE email_verification_id = #{id} AND company_id = #{companyId}
  AND verified_at IS NULL AND consumed_at IS NULL AND revoked_at IS NULL
  AND expires_at > #{now}

UPDATE email_verification
SET consumed_at = #{now}, updated_at = #{now}
WHERE email_verification_id = #{id} AND company_id = #{companyId}
  AND verified_at IS NOT NULL AND consumed_at IS NULL AND revoked_at IS NULL
  AND expires_at > #{now}
